const root = document.documentElement;
const dock = document.createElement('div');
dock.className='floating-controls';
dock.setAttribute('role','group');dock.setAttribute('aria-label','Display and scrolling controls');
dock.innerHTML=`<button class="theme-toggle" type="button" aria-label="Switch to light theme" title="Switch theme"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></button><span class="control-divider"></span><button type="button" data-scroll="up" aria-label="Scroll up" title="Scroll up"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 12 6-6 6 6M12 6v14"/></svg></button><button type="button" data-scroll="down" aria-label="Scroll down" title="Scroll down"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 12 6 6 6-6M12 4v14"/></svg></button>`;
document.body.append(dock);
const toggle=dock.querySelector('.theme-toggle');
function updateToggle(){const light=root.dataset.theme==='light';toggle.setAttribute('aria-label',`Switch to ${light?'dark':'light'} theme`);toggle.setAttribute('title',`Switch to ${light?'dark':'light'} theme`);toggle.setAttribute('aria-pressed',String(light));toggle.innerHTML=light?'<svg class="theme-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/></svg>':'<svg class="theme-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>';}
updateToggle();
toggle.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='light'?'dark':'light';try{localStorage.setItem('portfolio-theme',root.dataset.theme);}catch{}updateToggle();});
dock.querySelectorAll('[data-scroll]').forEach(button=>button.addEventListener('click',()=>window.scrollBy({top:innerHeight*.8*(button.dataset.scroll==='up'?-1:1),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})));
for(const a of document.querySelectorAll('nav a'))if(a.pathname===location.pathname)a.setAttribute('aria-current','page');
